const app=document.querySelector('#app');
const state={code:localStorage.rbCode||'',playerId:localStorage.rbPlayerId||'',room:null,error:'',actionType:'move',dir:'up',poll:null};
const api=async(op,data)=>{let url='/.netlify/functions/game';let options={headers:{'content-type':'application/json'}};if(data){options.method='POST';options.body=JSON.stringify({op,...data})}else{const [name,query='']=op.split('?');url+=`?op=${encodeURIComponent(name)}${query?'&'+query:''}`}const res=await fetch(url,options);const j=await res.json();if(!res.ok)throw new Error(j.error||'Request failed');return j};
function saveSession(){localStorage.rbCode=state.code;localStorage.rbPlayerId=state.playerId}
function clearSession(){localStorage.removeItem('rbCode');localStorage.removeItem('rbPlayerId');state.code='';state.playerId='';state.room=null;stopPoll();render()}
function me(){return state.room?.players.find(p=>p.id===state.playerId)}
function host(){return state.room?.hostId===state.playerId}
function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function setError(e){state.error=e?.message||String(e);render()}
async function refresh(){if(!state.code)return;try{const j=await api(`state?code=${encodeURIComponent(state.code)}`);state.room=j.room;state.error='';render()}catch(e){setError(e)}}
function startPoll(){stopPoll();state.poll=setInterval(refresh,700)}function stopPoll(){if(state.poll)clearInterval(state.poll);state.poll=null}
async function create(){try{const name=document.querySelector('#name').value;const j=await api('create',{name});state.playerId=j.playerId;state.code=j.room.code;state.room=j.room;saveSession();startPoll();render()}catch(e){setError(e)}}
async function join(){try{const name=document.querySelector('#name').value;const code=document.querySelector('#roomCode').value.toUpperCase();const j=await api('join',{name,code});state.playerId=j.playerId;state.code=code;state.room=j.room;saveSession();startPoll();render()}catch(e){setError(e)}}
async function ready(){try{const j=await api('ready',{code:state.code,playerId:state.playerId,ready:!me().ready});state.room=j.room;render()}catch(e){setError(e)}}
async function start(){try{const j=await api('start',{code:state.code,playerId:state.playerId});state.room=j.room;render()}catch(e){setError(e)}}
async function act(){try{const action={type:state.actionType};if(['move','blast','hack'].includes(state.actionType))action.dir=state.dir;const j=await api('action',{code:state.code,playerId:state.playerId,action});state.room=j.room;render()}catch(e){setError(e)}}
async function rematch(){try{const j=await api('rematch',{code:state.code,playerId:state.playerId});state.room=j.room;render()}catch(e){setError(e)}}
function home(){return `<div class="shell"><div class="brand"><div class="tag">Last Bot Standing</div><h1>ROBO BREAKERS</h1></div><div class="panel home">${err()}<p class="rules">2–8 players secretly choose commands. Everyone's actions resolve together. Outsmart, outblast, outlast.</p><input id="name" maxlength="16" placeholder="Your pilot name" value="Joe"><button class="btn primary" id="create">CREATE ROOM</button><div class="row"><input id="roomCode" maxlength="4" placeholder="ROOM CODE" style="flex:1;text-transform:uppercase"><button class="btn" id="join">JOIN</button></div><div class="rules"><b>How to play:</b> MOVE to reposition or ram, BLAST in a direction, SHIELD to block a blast, HACK adjacent bots to disable shields, or OVERCHARGE for energy. Last surviving robot wins.</div></div></div>`}
function err(){return state.error?`<div class="error">${esc(state.error)}</div>`:''}
function lobby(){const r=state.room;return `<div class="shell"><div class="brand"><div class="tag">Room <span class="code">${r.code}</span> <button class="copycode" id="copyCode" title="Copy room code">COPY</button></div><h1>ROBO BREAKERS</h1></div><div class="panel">${err()}<div class="roomhead"><div><b>Lobby</b><div class="status">Share code ${r.code} with another player.</div></div><button class="btn" id="leave">LEAVE</button></div><div class="players">${r.players.map(p=>`<div class="player"><b>${esc(p.name)}${p.id===r.hostId?' 👑':''}</b><div class="status">${p.id===r.hostId?'HOST':p.ready?'✅ READY':'⏳ NOT READY'}</div></div>`).join('')}</div><div class="row">${!host()?`<button class="btn ${me()?.ready?'good':''}" id="ready">${me()?.ready?'READY ✓':'READY UP'}</button>`:''}${host()?`<button class="btn primary" id="start" ${r.players.length<2?'disabled':''}>START MATCH</button>`:''}</div><p class="rules">Host can start once at least two players are here and every non-host player is ready.</p></div></div>`}
function board(){const r=state.room;let tiles='';for(let y=0;y<r.boardSize;y++){for(let x=0;x<r.boardSize;x++){const p=r.players.find(q=>q.alive&&q.x===x&&q.y===y);tiles+=`<div class="tile">${p?`<div class="bot ${p.id===state.playerId?'me':''}">${esc(p.name.slice(0,2).toUpperCase())}<span class="hp">${'❤'.repeat(Math.max(0,p.hp))}</span></div>`:''}</div>`}}return `<div class="board" style="grid-template-columns:repeat(${r.boardSize},1fr)">${tiles}</div>`}
function game(){const r=state.room,m=me();const locked=m?.lockedIn;return `<div class="shell"><div class="roomhead"><div><div class="tag">ROOM ${r.code}</div><h2 style="margin:.2rem 0">ROUND ${r.round}</h2></div><div><b>${esc(m?.name||'')}</b> · ${m?.hp??0} HP · ⚡ ${m?.energy??0}</div></div>${err()}<div class="gamegrid">${board()}<div class="side"><div class="panel"><b>Choose your command</b><div class="status">${locked?'LOCKED IN — waiting for other bots':'Your choice stays secret until everyone locks in.'}</div><div class="actions" style="margin-top:10px">${[['move','🏃 MOVE'],['blast','🔫 BLAST'],['shield','🛡 SHIELD'],['hack','💻 HACK'],['overcharge','⚡ OVERCHARGE']].map(([k,l])=>`<button class="btn action ${state.actionType===k?'selected':''}" data-action="${k}" ${locked||!m?.alive?'disabled':''}>${l}</button>`).join('')}</div>${['move','blast','hack'].includes(state.actionType)?`<div class="dirpad" style="margin-top:10px"><button class="btn up" data-dir="up">↑</button><button class="btn left" data-dir="left">←</button><button class="btn down" data-dir="down">↓</button><button class="btn right" data-dir="right">→</button></div><div class="status" style="text-align:center;margin-top:6px">Direction: ${state.dir.toUpperCase()}</div>`:''}<button class="btn primary" id="lock" style="width:100%;margin-top:12px" ${locked||!m?.alive?'disabled':''}>${m?.alive?'LOCK IN':'ELIMINATED'}</button></div><div class="panel"><b>Players</b><div class="players">${r.players.map(p=>`<div class="player"><b>${esc(p.name)}</b><div class="status">${p.alive?`${'❤'.repeat(p.hp)} · ⚡${p.energy} · ${p.lockedIn?'🔒':''}`:'☠ DECOMPILED'}</div></div>`).join('')}</div></div><div class="panel"><b>Combat Log</b><div class="log">${r.log.slice().reverse().map(x=>`<div>${esc(x)}</div>`).join('')}</div></div></div></div></div>`}
function finished(){const r=state.room;const winners=r.players.filter(p=>r.winnerIds.includes(p.id));return `<div class="shell"><div class="brand"><div class="tag">MATCH COMPLETE</div><h1>ROBO BREAKERS</h1></div><div class="panel winner">${err()}<h2>🏆 ${esc(winners.map(w=>w.name).join(' & ')||'DRAW')}</h2><p>LAST BOT STANDING</p><div class="players">${r.players.sort((a,b)=>b.eliminations-a.eliminations||b.damageDealt-a.damageDealt).map(p=>`<div class="player"><b>${esc(p.name)}</b><div class="status">${p.eliminations} KO · ${p.damageDealt} damage</div></div>`).join('')}</div>${host()?'<button class="btn primary" id="rematch">REMATCH</button>':'<p>Waiting for the host to start a rematch…</p>'}<button class="btn" id="leave" style="margin-left:8px">LEAVE</button></div></div>`}
function render(){app.innerHTML=!state.room?home():state.room.phase==='lobby'?lobby():state.room.phase==='playing'?game():finished();bind()}
function bind(){document.querySelector('#create')?.addEventListener('click',create);document.querySelector('#join')?.addEventListener('click',join);document.querySelector('#leave')?.addEventListener('click',clearSession);document.querySelector('#ready')?.addEventListener('click',ready);document.querySelector('#start')?.addEventListener('click',start);document.querySelector('#lock')?.addEventListener('click',act);document.querySelector('#rematch')?.addEventListener('click',rematch);document.querySelector('#copyCode')?.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(state.code);const b=document.querySelector('#copyCode');if(b){b.textContent='COPIED';setTimeout(()=>{if(document.querySelector('#copyCode'))document.querySelector('#copyCode').textContent='COPY'},1200)}}catch{setError(new Error('Could not copy room code.'))}});document.querySelectorAll('[data-action]').forEach(b=>b.addEventListener('click',()=>{state.actionType=b.dataset.action;render()}));document.querySelectorAll('[data-dir]').forEach(b=>b.addEventListener('click',()=>{state.dir=b.dataset.dir;render()}))}
if(state.code&&state.playerId){refresh().then(startPoll)}else render();
